public class Main {
    static int sum(int... nums) {
        System.out.println("  受け取った個数: " + nums.length);
        int total = 0;
        for (int n : nums) {
            total += n;
        }
        return total;
    }

    public static void main(String[] args) {
        System.out.println(sum(1, 2, 3));
        System.out.println(sum(10));
        System.out.println(sum());

        int[] a = {5, 5, 5};
        System.out.println(sum(a));      // 配列をそのまま渡せる
    }
}

public class Main {
    static void f(int a, int b) {
        System.out.println("固定2つの版");
    }

    static void f(int... a) {
        System.out.println("可変長の版（" + a.length + "個）");
    }

    public static void main(String[] args) {
        f(1, 2);        // 予想してから実行しよう
        f(1, 2, 3);
        f();
    }
}

