import java.util.Scanner;

public class Main {

    static int sum(int... nums) {
        int total = 0;
        for (int n : nums) {
            total += n;
        }
        return total;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int k = sc.nextInt();
        int[] nums = new int[k];
        for (int i = 0; i < k; i++) {
            nums[i] = sc.nextInt();
        }

        System.out.println("合計 " + sum(nums));
        System.out.println("引数なし " + sum());
    }
}
